public class InnerConnectionAuthenticationConfigurationInputFactory(Action<Humidifier.DataZone.ConnectionTypes.AuthenticationConfigurationInput> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.ConnectionTypes.AuthenticationConfigurationInput>
{

    internal InnerConnectionOAuth2PropertiesFactory OAuth2PropertiesFactory { get; set; }

    internal InnerConnectionBasicAuthenticationCredentialsFactory BasicAuthenticationCredentialsFactory { get; set; }

    protected override Humidifier.DataZone.ConnectionTypes.AuthenticationConfigurationInput Create()
    {
        var authenticationConfigurationInputResult = CreateAuthenticationConfigurationInput();
        factoryAction?.Invoke(authenticationConfigurationInputResult);

        return authenticationConfigurationInputResult;
    }

    private Humidifier.DataZone.ConnectionTypes.AuthenticationConfigurationInput CreateAuthenticationConfigurationInput()
    {
        var authenticationConfigurationInputResult = new Humidifier.DataZone.ConnectionTypes.AuthenticationConfigurationInput();

        return authenticationConfigurationInputResult;
    }
    public override void CreateChildren(Humidifier.DataZone.ConnectionTypes.AuthenticationConfigurationInput result)
    {
        base.CreateChildren(result);

        result.OAuth2Properties ??= OAuth2PropertiesFactory?.Build();
        result.BasicAuthenticationCredentials ??= BasicAuthenticationCredentialsFactory?.Build();
    }

} // End Of Class

